package com.mrorgar.q;

import androidx.webkit.ProxyController; import androidx.webkit.ProxyConfig; import android.app.*; import android.os.*; import android.content.*; import android.graphics.Bitmap; import android.graphics.Color; import android.graphics.Typeface; import android.net.Uri; import android.view.*; import android.view.inputmethod.*; import android.webkit.*; import android.widget.*; import android.text.InputType; import org.json.*; import java.io.*; import java.util.*;

public class MainActivity extends Activity {
    WebView web; EditText address; LinearLayout root, top; FrameLayout stage; Button restore; ValueCallback<Uri[]> uploadCallback; static final int PICK_FILE=601, PICK_MANUAL_UPLOAD=603, PICK_VRAY=602; boolean fullscreen=false; DownloadManager downloadManager;
    @Override public void onCreate(Bundle state){ super.onCreate(state); getWindow().setStatusBarColor(Color.rgb(32,33,36)); getWindow().setNavigationBarColor(Color.BLACK); buildUI(); configureWeb(); if(state==null) web.loadUrl("https://www.google.com"); }
    int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+0.5f);} 
    void buildUI(){
        root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setBackgroundColor(Color.WHITE);
        top=new LinearLayout(this); top.setOrientation(LinearLayout.HORIZONTAL); top.setGravity(Gravity.CENTER_VERTICAL); top.setBackgroundColor(Color.rgb(32,33,36));
        String[] names={"Back","Forward","Send","File","Copy MW","IP Set","Save","F Screen"};
        for(String n:names){ Button b=new Button(this); b.setText(n); b.setTextSize(8.5f); b.setTextColor(Color.WHITE); b.setAllCaps(false); b.setPadding(0,0,0,0); b.setMinWidth(0); b.setMinimumWidth(0); b.setMinHeight(0); b.setMinimumHeight(0); b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(45,46,49))); top.addView(b,new LinearLayout.LayoutParams(0,dp(38),1)); b.setOnClickListener(v->doAction(n)); }
        root.addView(top,new LinearLayout.LayoutParams(-1,dp(38)));
        // Long-press Save opens the multi-download queue; a normal tap still saves the current page.
        top.getChildAt(6).setOnLongClickListener(v->{multiDownloadDialog(); return true;});
        address=new EditText(this); address.setSingleLine(true); address.setTextSize(14); address.setHint("Website or search words"); address.setPadding(dp(10),0,dp(8),0); address.setImeOptions(EditorInfo.IME_ACTION_GO); address.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI); root.addView(address,new LinearLayout.LayoutParams(-1,dp(42)));
        stage=new FrameLayout(this); web=new WebView(this); stage.addView(web,new FrameLayout.LayoutParams(-1,-1));
        restore=new Button(this); restore.setText("↙"); restore.setTextSize(18); restore.setAllCaps(false); restore.setPadding(0,0,0,0); restore.setTextColor(0xCCFFFFFF); restore.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0x33808080)); restore.setVisibility(View.GONE); FrameLayout.LayoutParams rp=new FrameLayout.LayoutParams(dp(44),dp(44),Gravity.RIGHT|Gravity.CENTER_VERTICAL); rp.rightMargin=dp(5); stage.addView(restore,rp); restore.setOnClickListener(v->setFullscreen(false));
        // Keep the restore control draggable so it can be moved away from page controls.
        restore.setOnTouchListener(new View.OnTouchListener(){float dx,dy; public boolean onTouch(View v,android.view.MotionEvent e){FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)v.getLayoutParams(); if(e.getAction()==MotionEvent.ACTION_DOWN){dx=e.getRawX()-p.rightMargin;dy=e.getRawY()-p.topMargin;return false;} if(e.getAction()==MotionEvent.ACTION_MOVE){p.gravity=Gravity.TOP|Gravity.LEFT;p.leftMargin=(int)(e.getRawX()-dx);p.topMargin=(int)(e.getRawY()-dy);p.rightMargin=0;v.setLayoutParams(p);return true;} return false;}});
        root.addView(stage,new LinearLayout.LayoutParams(-1,0,1)); setContentView(root);
        address.setOnEditorActionListener((v,id,event)->{loadAddress();return true;});
    }
    void configureWeb(){ WebSettings s=web.getSettings(); s.setJavaScriptEnabled(true); s.setDomStorageEnabled(true); s.setDatabaseEnabled(true); s.setLoadWithOverviewMode(true); s.setUseWideViewPort(true); s.setSupportMultipleWindows(false); s.setJavaScriptCanOpenWindowsAutomatically(false); s.setLoadsImagesAutomatically(true); s.setAllowFileAccess(true); s.setAllowContentAccess(true); s.setMediaPlaybackRequiresUserGesture(false);
        // Request desktop site without launching an external browser.
        String ua=s.getUserAgentString().replace("Mobile","").replace("Android", "X11; Linux x86_64"); s.setUserAgentString(ua);
        web.setWebViewClient(new WebViewClient(){ @Override public boolean shouldOverrideUrlLoading(WebView view, WebResourceRequest req){String sc=req.getUrl().getScheme(); if("http".equalsIgnoreCase(sc)||"https".equalsIgnoreCase(sc)||"about".equalsIgnoreCase(sc)||"data".equalsIgnoreCase(sc)||"blob".equalsIgnoreCase(sc))return false; toast("این نوع پیوند در WebView پشتیبانی نمی‌شود؛ مرورگر دیگری باز نخواهد شد."); return true;} @Override public void onPageStarted(WebView v,String u,Bitmap f){address.setText(u);} @Override public void onPageFinished(WebView v,String u){address.setText(u);} });
        web.setWebChromeClient(new WebChromeClient(){ @Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams params){ if(uploadCallback!=null)uploadCallback.onReceiveValue(null); uploadCallback=cb; try{Intent i=params.createIntent(); i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true); startActivityForResult(i,PICK_FILE);}catch(Exception ex){uploadCallback=null;cb.onReceiveValue(null);toast("بازکردن انتخاب‌گر فایل ناموفق بود");} return true;} @Override public void onProgressChanged(WebView v,int progress){setTitle("Mrorgar-Q • "+progress+"%");} });
        downloadManager=(DownloadManager)getSystemService(DOWNLOAD_SERVICE);
        web.setDownloadListener((url, userAgent, contentDisposition, mimetype, contentLength)->enqueueDownload(url,userAgent,contentDisposition,mimetype));
    }
    void loadAddress(){String q=address.getText().toString().trim();if(q.isEmpty())return;String u;if(q.matches("(?i)^[a-z][a-z0-9+.-]*://.*"))u=q;else if(q.contains(" ")||!q.contains("."))u="https://www.google.com/search?q="+Uri.encode(q);else u="https://"+q;web.loadUrl(u);((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(address.getWindowToken(),0);}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    void doAction(String a){switch(a){case "Back":if(web.canGoBack())web.goBack();break;case "Forward":if(web.canGoForward())web.goForward();break;case "Send":sendContent();break;case "File":pickAnyFile();break;case "Copy MW":copyPage();break;case "IP Set":ipSettings();break;case "Save":savePage();break;case "F Screen":setFullscreen(!fullscreen);break;}}
    void sendContent(){String u=web.getUrl()==null?"":web.getUrl();String title=web.getTitle()==null?u:web.getTitle();Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_SUBJECT,title);i.putExtra(Intent.EXTRA_TEXT,u);try{startActivity(Intent.createChooser(i,"Send link or message"));}catch(Exception e){toast("برنامه‌ای برای ارسال پیدا نشد");}}
    void pickAnyFile(){
        // Trigger the active page's real file input, so the selected files are returned to the site.
        web.evaluateJavascript("(function(){var a=[].slice.call(document.querySelectorAll('input[type=file]'));if(!a.length)return false; a[0].click(); return true;})()", result->{
            if("true".equals(result)){return;}
            // No upload field exists on this page. Still allow choosing files, but do not falsely claim they were uploaded.
            Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);
            try{startActivityForResult(i,PICK_MANUAL_UPLOAD);}catch(Exception e){toast("انتخاب‌گر فایل در دسترس نیست");}
        });
    }
    void enqueueDownload(String url,String ua,String disposition,String mime){
        try{DownloadManager.Request r=new DownloadManager.Request(Uri.parse(url));r.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);r.setAllowedOverMetered(true);r.setAllowedOverRoaming(true);if(mime!=null&&!mime.isEmpty())r.setMimeType(mime);if(ua!=null)r.addRequestHeader("User-Agent",ua);String cookies=CookieManager.getInstance().getCookie(url);if(cookies!=null)r.addRequestHeader("Cookie",cookies);String name=URLUtil.guessFileName(url,disposition,mime);r.setTitle(name);r.setDescription("Mrorgar-Q download queue");downloadManager.enqueue(r);toast("به صف دانلود اضافه شد: "+name);}catch(Exception e){toast("افزودن دانلود ناموفق بود");}
    }
    void multiDownloadDialog(){
        LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(4),dp(18),0);
        TextView help=new TextView(this);help.setText("هر لینک دانلود را در یک خط وارد کن. لینک‌های مستقیم HTTP/HTTPS به صف دانلود اندروید اضافه می‌شوند.");box.addView(help);
        EditText links=new EditText(this);links.setSingleLine(false);links.setMinLines(4);links.setGravity(Gravity.TOP|Gravity.START);links.setHint("https://example.com/file1.zip\nhttps://example.com/file2.pdf");box.addView(links);
        new AlertDialog.Builder(this).setTitle("Multi Downloader").setView(box).setPositiveButton("Add to queue",(d,w)->{String[] rows=links.getText().toString().split("\\r?\\n");int count=0;for(String row:rows){String u=row.trim();if(u.matches("(?i)^https?://.+")){enqueueDownload(u,web.getSettings().getUserAgentString(),null,null);count++;}}if(count==0)toast("لینک مستقیم HTTP/HTTPS وارد نشده است");else toast(count+" لینک به صف دانلود اضافه شد");}).setNeutralButton("View downloads",(d,w)->showDownloads()).setNegativeButton("Cancel",null).show();
    }
    void showDownloads(){
        if(downloadManager==null)return;DownloadManager.Query q=new DownloadManager.Query();android.database.Cursor c=downloadManager.query(q);StringBuilder b=new StringBuilder();try{while(c!=null&&c.moveToNext()){String title=c.getString(c.getColumnIndex(DownloadManager.COLUMN_TITLE));int status=c.getInt(c.getColumnIndex(DownloadManager.COLUMN_STATUS));long done=c.getLong(c.getColumnIndex(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR));long total=c.getLong(c.getColumnIndex(DownloadManager.COLUMN_TOTAL_SIZE_BYTES));String state=status==DownloadManager.STATUS_SUCCESSFUL?"Completed":status==DownloadManager.STATUS_FAILED?"Failed":status==DownloadManager.STATUS_PAUSED?"Paused":"Downloading";b.append(title).append(" — ").append(state);if(total>0)b.append(" ( ").append((done*100/total)).append("% )");b.append('\n');}}finally{if(c!=null)c.close();}if(b.length()==0)b.append("صف دانلود خالی است.");new AlertDialog.Builder(this).setTitle("Downloads").setMessage(b.toString()).setPositiveButton("Refresh",(d,w)->showDownloads()).setNegativeButton("Close",null).show();
    }
    void copyPage(){web.evaluateJavascript("(function(){return document.documentElement.outerHTML})()",val->{String html=val;try{html=new JSONTokener(val).nextValue().toString();}catch(Exception ignored){} android.content.ClipboardManager cm=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("Web page HTML",html));toast("HTML صفحه کپی شد");});}
    EditText field(String hint,int type){EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(14);e.setHint(hint);e.setInputType(type);return e;}
    void ipSettings(){String[] items={"Proxy Port","DNS (Primary / Secondary)","Tunnel","Vray"};new AlertDialog.Builder(this).setTitle("IP Set").setItems(items,(d,w)->{if(w==0)proxySettings();else if(w==1)dnsSettings();else if(w==2)tunnelSettings();else vraySettings();}).setNegativeButton("Close",null).show();}
    void proxySettings(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(4),dp(18),0);EditText host=field("Proxy host / IP",InputType.TYPE_CLASS_TEXT);EditText port=field("Proxy port",InputType.TYPE_CLASS_NUMBER);box.addView(host);box.addView(port);String old=getPreferences(0).getString("proxy_host","");host.setText(old);port.setText(getPreferences(0).getString("proxy_port",""));new AlertDialog.Builder(this).setTitle("Proxy Port").setView(box).setPositiveButton("Apply",(d,w)->applyProxy(host.getText().toString().trim(),port.getText().toString().trim())).setNeutralButton("Disable",(d,w)->disableProxy()).setNegativeButton("Cancel",null).show();}
    void applyProxy(String host,String port){if(host.isEmpty()||port.isEmpty()){toast("آدرس و پورت را وارد کن");return;}try{int p=Integer.parseInt(port);if(p<1||p>65535)throw new IllegalArgumentException();getPreferences(0).edit().putString("proxy_host",host).putString("proxy_port",port).apply();if(Build.VERSION.SDK_INT>=28){androidx.webkit.ProxyController.getInstance().setProxyOverride(new androidx.webkit.ProxyConfig.Builder().addProxyRule(host+":"+p).build(),getMainExecutor(),()->toast("Proxy برای WebView اعمال شد"));}else{toast("پراکسی WebView به Android 9 یا بالاتر نیاز دارد؛ تنظیمات ذخیره شد.");}}catch(NumberFormatException e){toast("آدرس یا پورت معتبر نیست");}catch(IllegalArgumentException e){toast("آدرس یا پورت معتبر نیست");}}
    void disableProxy(){if(Build.VERSION.SDK_INT>=28){androidx.webkit.ProxyController.getInstance().clearProxyOverride(getMainExecutor(),()->toast("Proxy غیرفعال شد"));}else{toast("این نسخهٔ اندروید API لازم برای پاک‌کردن پراکسی WebView را ندارد");}}
    void dnsSettings(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(4),dp(18),0);EditText a=field("Primary DNS",InputType.TYPE_CLASS_TEXT);EditText b=field("Secondary DNS",InputType.TYPE_CLASS_TEXT);a.setText(getPreferences(0).getString("dns1",""));b.setText(getPreferences(0).getString("dns2",""));box.addView(a);box.addView(b);new AlertDialog.Builder(this).setTitle("DNS settings").setView(box).setPositiveButton("Save",(d,w)->{getPreferences(0).edit().putString("dns1",a.getText().toString().trim()).putString("dns2",b.getText().toString().trim()).apply();new AlertDialog.Builder(this).setTitle("DNS saved").setMessage("آدرس‌ها ذخیره شدند؛ این کار به‌تنهایی DNS سیستم یا درخواست‌های WebView را تغییر نمی‌دهد. برای اعمال DNS واقعی باید DoH/DoT یا VPN محلی پیاده‌سازی شود.").setPositiveButton("OK",null).show();}).setNegativeButton("Cancel",null).show();}
    void tunnelSettings(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(4),dp(18),0);EditText kind=field("Tunnel type (e.g. SOCKS5 / HTTP)",InputType.TYPE_CLASS_TEXT);EditText endpoint=field("Server host:port",InputType.TYPE_CLASS_TEXT);EditText note=field("Credentials / config (optional)",InputType.TYPE_CLASS_TEXT);box.addView(kind);box.addView(endpoint);box.addView(note);kind.setText(getPreferences(0).getString("tunnel_type",""));endpoint.setText(getPreferences(0).getString("tunnel_endpoint",""));note.setText(getPreferences(0).getString("tunnel_config",""));new AlertDialog.Builder(this).setTitle("Tunnel").setView(box).setPositiveButton("Save",(d,w)->{getPreferences(0).edit().putString("tunnel_type",kind.getText().toString()).putString("tunnel_endpoint",endpoint.getText().toString()).putString("tunnel_config",note.getText().toString()).apply();toast("تنظیمات Tunnel ذخیره شد؛ برای اتصال واقعی موتور تونل و سرویس VPN لازم است.");}).setNeutralButton("Disconnect",(d,w)->toast("تونلی از داخل این نسخه فعال نشده است")).setNegativeButton("Cancel",null).show();}
    void vraySettings(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(4),dp(18),0);EditText config=field("V2Ray config JSON or vmess:// / vless:// link",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);config.setSingleLine(false);config.setMinLines(3);config.setText(getPreferences(0).getString("vray_config",""));box.addView(config);new AlertDialog.Builder(this).setTitle("Vray / V2Ray").setView(box).setPositiveButton("Save config",(d,w)->{getPreferences(0).edit().putString("vray_config",config.getText().toString().trim()).apply();toast("کانفیگ ذخیره شد؛ اتصال V2Ray تا زمان افزودن موتور V2Ray برقرار نمی‌شود.");}).setNeutralButton("Import file",(d,w)->{Intent i=new Intent(Intent.ACTION_GET_CONTENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,PICK_VRAY);}catch(Exception e){toast("انتخاب فایل ممکن نیست");}}).setNegativeButton("Cancel",null).show();}
    void savePage(){web.evaluateJavascript("(function(){return document.documentElement.outerHTML})()",val->{String html;try{html=new JSONTokener(val).nextValue().toString();}catch(Exception e){html=val;}try{File dir=getExternalFilesDir(Environment.DIRECTORY_DOWNLOADS);if(dir==null)dir=getFilesDir();File out=new File(dir,"Mrorgar-Q_page_"+System.currentTimeMillis()+".html");try(FileWriter fw=new FileWriter(out)){fw.write(html);}toast("صفحه ذخیره شد: "+out.getName());}catch(Exception e){toast("ذخیره صفحه ناموفق بود");}});}
    void setFullscreen(boolean enable){fullscreen=enable;if(enable){top.setVisibility(View.GONE);address.setVisibility(View.GONE);restore.setVisibility(View.VISIBLE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_LAYOUT_STABLE);}else{getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_VISIBLE);top.setVisibility(View.VISIBLE);address.setVisibility(View.VISIBLE);restore.setVisibility(View.GONE);}}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==PICK_VRAY&&result==RESULT_OK&&data!=null&&data.getData()!=null){try(java.io.InputStream in=getContentResolver().openInputStream(data.getData())){byte[] buf=new byte[8192];java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();int n;while((n=in.read(buf))>0)out.write(buf,0,n);String text=new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);getPreferences(0).edit().putString("vray_config",text).apply();toast("فایل کانفیگ وارد شد");}catch(Exception e){toast("خواندن فایل کانفیگ ناموفق بود");}return;}if(req==PICK_FILE&&uploadCallback!=null){Uri[] res=null;if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){int n=data.getClipData().getItemCount();res=new Uri[n];for(int j=0;j<n;j++)res[j]=data.getClipData().getItemAt(j).getUri();}else if(data.getData()!=null)res=new Uri[]{data.getData()};}uploadCallback.onReceiveValue(res);uploadCallback=null;}else if(req==PICK_MANUAL_UPLOAD&&result==RESULT_OK&&data!=null){int n=data.getClipData()!=null?data.getClipData().getItemCount():(data.getData()!=null?1:0);toast(n+" فایل انتخاب شد؛ برای آپلود باید صفحهٔ سایت یک فرم انتخاب فایل داشته باشد.");}}
    @Override public void onBackPressed(){if(fullscreen){setFullscreen(false);return;}if(web!=null&&web.canGoBack())web.goBack();else super.onBackPressed();}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(web!=null)b.putString("url",web.getUrl());}
    @Override protected void onDestroy(){if(web!=null){web.stopLoading();web.destroy();}super.onDestroy();}
}
